begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $native$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1750 then raise exception 'NATIVE_CAMPAIGN_CHANGED';end if;if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:9a1b04c90dc0a3418eadcb5a' and md5(to_jsonb(t)::text)='1fcc56ba707b37c71e4a7c3e60b10af7')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:9a1b04c90dc0a3418eadcb5a';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition}',$native_1c95a49447662684${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:9a1b04c90dc0a3418eadcb5a","revision":1,"language":"es","name":"Bastón de poder","aliases":[],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:03af344e2dbd05576d85b8d8b19d7f9feb9272511633f4816b50330e1f55fe9d","kind":"legacy","title":"Bastón de poder","language":"es","rulesEdition":null,"locator":"official:equipment:es:9a1b04c90dc0a3418eadcb5a","verified":false},{"id":"original:9c40e8c32ad3d17fc8f3b449c8038592952adadbe1d4dcd16643a8bbe82ed3a5","kind":"legacy","title":"Bastón de poder","language":"es","rulesEdition":null,"locator":"official:equipment:es:9a1b04c90dc0a3418eadcb5a","verified":false},{"id":"original:ae78ece6659f370e1275b5b20db5d359241a7b7c9d018d8ed53103117069517f","kind":"legacy","title":"Staff of Power","language":"en","rulesEdition":null,"locator":"official:equipment:eng:3dab6ab3a242400a50d51f2e","verified":false},{"id":"original:c084235bc4bedc4ffd8283d4a7b3d97126f3952b032e9669475b2dd10768da9d","kind":"legacy","title":"Staff of Power","language":"en","rulesEdition":null,"locator":"official:equipment:eng:3dab6ab3a242400a50d51f2e","verified":false},{"id":"srd-5.1-es-equipment","kind":"srd","title":"SRD 5.1 · edición oficial española","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · página PDF 235 · CC BY 4.0","verified":true}],"category":"staff","subtypes":[],"magical":true,"rarity":"very-rare","consumable":false,"properties":["versatile"],"weight":{"value":4,"unit":"lb"},"economy":{"basePrice":null,"campaignPrice":null,"explanation":""},"description":[{"id":"official-block-0","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a la Clase de Armadura, las tiradas de salvación y las tiradas de ataque de conjuro."},{"id":"official-block-1","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"El bastón tiene 20 cargas para utilizar las propiedades que se describen a continuación. El bastón recupera 2d8 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón conserva su bonifi- cador de +2 a las tiradas de ataque y de daño, pero pierde sus otras propiedades. Si el resultado es 20, el bastón recupera 1d8 + 2 cargas."},{"id":"official-block-2","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Golpe de poder. Cuando impactes con un ataque cuerpo a cuerpo con el bastón, podrás gastar 1 carga para infligir 1d6 de daño de fuerza adicional al objetivo."},{"id":"official-block-3","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Conjuros. Mientras empuñes este bastón, puedes usar una acción y gastar 1 o más de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y bonificador de ataque de conjuro: bola de fuego (versión de nivel 5, 5 cargas), cono de frío (5 cargas), globo de invulnerabilidad (6 cargas), inmovilizar monstruo (5 cargas), levitar (2 cargas), muro de fuerza (5 cargas), proyectil mágico (1 carga), rayo debilitador (1 carga) o relámpago (versión de nivel 5, 5 cargas)."},{"id":"official-block-4","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Golpe vengador. Puedes usar una acción para romper el bastón de un rodillazo o contra una superficie sólida, lo que ejecuta un golpe vengador. El bastón se destruye y libera la magia que le queda a modo de explosión que se extiende para cubrir una esfera de 9 m de radio centrada en él."},{"id":"official-block-5","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Tienes un 50 por ciento de probabilidad de viajar en ese instante a un plano de existencia aleatorio y evitar la explosión. Si no logras evitar el efecto, sufrirás una cantidad de daño de fuerza igual a 16 veces el número de cargas del bastón. Todas las demás criaturas situadas en esa zona deberán hacer una tirada de salvación de Destreza con CD 17. Si la fallan, sufrirán daño conforme a la distancia a la que se encuentren del punto de origen, tal y como se muestra en la siguiente tabla. Si la superan, recibirán la mitad de ese daño."},{"id":"official-block-6","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"table","columns":["Distancia del origen","Daño"],"rows":[["3 m de distancia o más","8 veces el número de cargas"],["cerca","del bastón"],["De 4 m a 6 m de","6 veces el número de cargas"],["distancia","del bastón"],["De 7 m a 9 m de","4 veces el número de cargas"],["distancia","del bastón"]]}],"requirements":{"attunement":true,"bearer":[{"kind":"class","keys":["wizard","warlock","sorcerer"],"explanation":"Bastón, muy raro (requiere sintonización por parte de un brujo, hechicero o mago)"}],"presence":"held","explanation":"Bastón, muy raro (requiere sintonización por parte de un brujo, hechicero o mago)"},"weapon":{"category":"simple","meleeReachFeet":5,"thrown":false,"rangeFeet":null,"attackBonus":2,"damageBonus":2,"baseDamage":[{"id":"base-damage","condition":"","kind":"damage","expression":"1d6","damageType":"bludgeoning","timing":"base"},{"id":"versatile-damage","condition":"Empleada a dos manos en un ataque cuerpo a cuerpo.","kind":"damage","expression":"1d8","damageType":"bludgeoning","timing":"versatile"}]},"armor":null,"resources":[{"id":"charges","name":"Cargas","kind":"charges","maximum":20,"unit":"cargas","recovery":{"kind":"event","event":"dawn","explanation":"Recuperación indicada por la fuente al amanecer.","amount":{"kind":"roll","expression":"2d8+4"}},"exhaustion":"Aplicar las consecuencias particulares de la descripción cuando se gasten sus cargas."}],"capabilities":[{"id":"verified-passive-bonuses","name":"Bonos del objeto","activation":"passive","trigger":"","requirements":{"attunement":true,"bearer":[{"kind":"class","keys":["wizard","warlock","sorcerer"],"explanation":"Bastón, muy raro (requiere sintonización por parte de un brujo, hechicero o mago)"}],"presence":"held","explanation":"Bastón, muy raro (requiere sintonización por parte de un brujo, hechicero o mago)"},"target":"Portador","range":"","duration":"Mientras se cumplen los requisitos.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"passive-0","condition":"Mientras se lleva o empuña y se cumple la sintonización indicada.","kind":"bonus","target":"spell-attack","operation":"add","value":2},{"id":"passive-1","condition":"Mientras se lleva o empuña y se cumple la sintonización indicada.","kind":"bonus","target":"saving-throws","operation":"add","value":2},{"id":"passive-2","condition":"Mientras se lleva o empuña y se cumple la sintonización indicada.","kind":"bonus","target":"armor-class","operation":"add","value":2}],"execution":{"mode":"automatic","handler":"equipment-passive-bonus","explanation":"Se aplica y retira con los requisitos del objeto.","pendingAutomation":[]},"textBlockIds":["official-block-0","official-block-1","official-block-2","official-block-3","official-block-4","official-block-5","official-block-6"]},{"id":"official-2014-rule","name":"Reglas de la variante","activation":"other","trigger":"","requirements":{"attunement":true,"bearer":[{"kind":"class","keys":["wizard","warlock","sorcerer"],"explanation":"Bastón, muy raro (requiere sintonización por parte de un brujo, hechicero o mago)"}],"presence":"held","explanation":"Bastón, muy raro (requiere sintonización por parte de un brujo, hechicero o mago)"},"target":"Según la regla oficial.","range":"","duration":"Según la regla oficial.","concentration":"spell-dependent","costs":[],"consumeQuantity":0,"effects":[{"id":"source-rule","condition":"","kind":"unmodeled","explanation":"Resolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.","original":{"index":"staff-of-power","source":"srd-5.1-es-equipment","subtype":null}}],"execution":{"mode":"assisted","handler":"equipment-text-assistance","explanation":"Descripción y variante cotejadas. El consumo de una poción se registra; el resto de efectos y gastos se resuelve según la regla concreta.","pendingAutomation":["Conectar las elecciones, objetivos, costes variables, duración y efectos particulares de esta regla.","Registrar los gastos reales de cargas y resolver las consecuencias de la última carga según la descripción."]},"textBlockIds":["official-block-0","official-block-1","official-block-2","official-block-3","official-block-4","official-block-5","official-block-6"]},{"id":"last-charge-check","name":"Última carga","activation":"trigger","trigger":"Al gastar la última carga del objeto.","requirements":{"attunement":true,"bearer":[{"kind":"class","keys":["wizard","warlock","sorcerer"],"explanation":"Bastón, muy raro (requiere sintonización por parte de un brujo, hechicero o mago)"}],"presence":"held","explanation":"Bastón, muy raro (requiere sintonización por parte de un brujo, hechicero o mago)"},"target":"El objeto","range":"","duration":"Instantánea","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"last-charge-outcome","kind":"last-charge-resolution","condition":"Después de gastar la última carga.","sides":20,"outcome":"replace","replacementKey":"official:equipment:es:f8e1af7cfa4f2f98cf87df55","refillOnMaximum":"1d8+2"}],"execution":{"mode":"automatic","handler":"equipment-last-charge","explanation":"Aplica la consecuencia y, cuando corresponde, valida el d20 y la tirada de recuperación. Conserva la identidad del ejemplar y actualiza su forma, ataques y conjuros.","pendingAutomation":[]},"textBlockIds":["official-block-1"]}],"recoverySourceIds":["03af344e2dbd05576d85b8d8b19d7f9feb9272511633f4816b50330e1f55fe9d","9c40e8c32ad3d17fc8f3b449c8038592952adadbe1d4dcd16643a8bbe82ed3a5","ae78ece6659f370e1275b5b20db5d359241a7b7c9d018d8ed53103117069517f","c084235bc4bedc4ffd8283d4a7b3d97126f3952b032e9669475b2dd10768da9d"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":false,"unresolved":["Conservar originales y cerrar su recuperación antes de eliminar versiones."]}}$native_1c95a49447662684$::jsonb,true),'{features}',$native_d211c7a9b9bf3f24$[{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a la Clase de Armadura, las tiradas de salvación y las tiradas de ataque de conjuro.\n\nEl bastón tiene 20 cargas para utilizar las propiedades que se describen a continuación. El bastón recupera 2d8 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón conserva su bonifi- cador de +2 a las tiradas de ataque y de daño, pero pierde sus otras propiedades. Si el resultado es 20, el bastón recupera 1d8 + 2 cargas.\n\nGolpe de poder. Cuando impactes con un ataque cuerpo a cuerpo con el bastón, podrás gastar 1 carga para infligir 1d6 de daño de fuerza adicional al objetivo.\n\nConjuros. Mientras empuñes este bastón, puedes usar una acción y gastar 1 o más de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y bonificador de ataque de conjuro: bola de fuego (versión de nivel 5, 5 cargas), cono de frío (5 cargas), globo de invulnerabilidad (6 cargas), inmovilizar monstruo (5 cargas), levitar (2 cargas), muro de fuerza (5 cargas), proyectil mágico (1 carga), rayo debilitador (1 carga) o relámpago (versión de nivel 5, 5 cargas).\n\nGolpe vengador. Puedes usar una acción para romper el bastón de un rodillazo o contra una superficie sólida, lo que ejecuta un golpe vengador. El bastón se destruye y libera la magia que le queda a modo de explosión que se extiende para cubrir una esfera de 9 m de radio centrada en él.\n\nTienes un 50 por ciento de probabilidad de viajar en ese instante a un plano de existencia aleatorio y evitar la explosión. Si no logras evitar el efecto, sufrirás una cantidad de daño de fuerza igual a 16 veces el número de cargas del bastón. Todas las demás criaturas situadas en esa zona deberán hacer una tirada de salvación de Destreza con CD 17. Si la fallan, sufrirán daño conforme a la distancia a la que se encuentren del punto de origen, tal y como se muestra en la siguiente tabla. Si la superan, recibirán la mitad de ese daño.\n\n3 m de distancia o más · 8 veces el número de cargas\ncerca · del bastón\nDe 4 m a 6 m de · 6 veces el número de cargas\ndistancia · del bastón\nDe 7 m a 9 m de · 4 veces el número de cargas\ndistancia · del bastón\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a la Clase de Armadura, las tiradas de salvación y las tiradas de ataque de conjuro.\n\nEl bastón tiene 20 cargas para utilizar las propiedades que se describen a continuación. El bastón recupera 2d8 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón conserva su bonifi- cador de +2 a las tiradas de ataque y de daño, pero pierde sus otras propiedades. Si el resultado es 20, el bastón recupera 1d8 + 2 cargas.\n\nGolpe de poder. Cuando impactes con un ataque cuerpo a cuerpo con el bastón, podrás gastar 1 carga para infligir 1d6 de daño de fuerza adicional al objetivo.\n\nConjuros. Mientras empuñes este bastón, puedes usar una acción y gastar 1 o más de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y bonificador de ataque de conjuro: bola de fuego (versión de nivel 5, 5 cargas), cono de frío (5 cargas), globo de invulnerabilidad (6 cargas), inmovilizar monstruo (5 cargas), levitar (2 cargas), muro de fuerza (5 cargas), proyectil mágico (1 carga), rayo debilitador (1 carga) o relámpago (versión de nivel 5, 5 cargas).\n\nGolpe vengador. Puedes usar una acción para romper el bastón de un rodillazo o contra una superficie sólida, lo que ejecuta un golpe vengador. El bastón se destruye y libera la magia que le queda a modo de explosión que se extiende para cubrir una esfera de 9 m de radio centrada en él.\n\nTienes un 50 por ciento de probabilidad de viajar en ese instante a un plano de existencia aleatorio y evitar la explosión. Si no logras evitar el efecto, sufrirás una cantidad de daño de fuerza igual a 16 veces el número de cargas del bastón. Todas las demás criaturas situadas en esa zona deberán hacer una tirada de salvación de Destreza con CD 17. Si la fallan, sufrirán daño conforme a la distancia a la que se encuentren del punto de origen, tal y como se muestra en la siguiente tabla. Si la superan, recibirán la mitad de ese daño.\n\n3 m de distancia o más · 8 veces el número de cargas\ncerca · del bastón\nDe 4 m a 6 m de · 6 veces el número de cargas\ndistancia · del bastón\nDe 7 m a 9 m de · 4 veces el número de cargas\ndistancia · del bastón\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$native_d211c7a9b9bf3f24$::jsonb,true),'{charges}',$native_6e886f402073c1ab${"reset":"manual","current":20,"maximum":20}$native_6e886f402073c1ab$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:9a1b04c90dc0a3418eadcb5a';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:b97890f2fdedbce0fbe843c2' and md5(to_jsonb(t)::text)='9b84a32489bb97ae3f2a76213cec925d')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:b97890f2fdedbce0fbe843c2';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition}',$native_444edd58c45ede93${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:b97890f2fdedbce0fbe843c2","revision":1,"language":"es","name":"Talismán del mal definitivo","aliases":["Talismán Del Mal Definitivo"],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:b9bb410fc1dc7cca76c469ab345b983a829aa739eda2599bc5fe5b2c84255139","kind":"legacy","title":"Talismán Del Mal Definitivo","language":"es","rulesEdition":null,"locator":"official:equipment:es:b97890f2fdedbce0fbe843c2","verified":false},{"id":"original:a92f21d9cc5191c2ac40fd56751e881ebdaf640e5cf84fe108ee61c134438a14","kind":"legacy","title":"Talismán Del Mal Definitivo","language":"es","rulesEdition":null,"locator":"official:equipment:es:b97890f2fdedbce0fbe843c2","verified":false},{"id":"original:b693b1d8ee181089be318ede3437ad04f7ddfbead15be306688265dc0aa60466","kind":"legacy","title":"Talisman of Ultimate Evil","language":"en","rulesEdition":null,"locator":"official:equipment:eng:d0b13de91dab31fc3546a2e6","verified":false},{"id":"original:c1c9369ba7ea5282e953ca1b7f20d36d26a209cdeb551f890fe0e6942e59836d","kind":"legacy","title":"Talisman of Ultimate Evil","language":"en","rulesEdition":null,"locator":"official:equipment:eng:d0b13de91dab31fc3546a2e6","verified":false},{"id":"srd-5.1-es-equipment","kind":"srd","title":"Documento de referencia del sistema 5.1 · edición oficial española","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · página PDF 263 · CC BY 4.0","verified":true}],"category":"wondrous-item","subtypes":[],"magical":true,"rarity":"legendary","consumable":false,"properties":[],"weight":null,"economy":{"basePrice":null,"campaignPrice":null,"explanation":""},"description":[{"id":"official-rule-0","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Este objeto simboliza el mal impenitente. Una criatura cuyo alineamiento no sea ni bueno ni malvado sufrirá 6d6 de daño necrótico si lo toca. En cambio, si es de alineamiento bueno, sufrirá 8d6 de daño necrótico. En ambos casos, la criatura sufrirá el daño de nuevo cada vez que sostenga o lleve puesto el talismán al terminar su turno."},{"id":"official-rule-1","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Si eres un clérigo o paladín malvado, puedes usar el talismán como símbolo sagrado y obtienes un bonificador de +2 a las tiradas de ataque de conjuro mientras lo lleves puesto o lo sostengas."},{"id":"official-rule-2","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"El talismán tiene 6 cargas. Si lo llevas puesto o lo sostienes, puedes usar una acción para gastar 1 de sus cargas y elegir una criatura que puedas ver en el suelo a 36 m o menos de ti. Si el objetivo tiene alineamiento bueno, una grieta ardiente se abrirá bajo él. Deberá superar una tirada de salvación de Destreza con CD 20 o se caerá por la grieta y será destruido sin dejar ningún resto mortal. A continuación, la grieta se cerrará y no quedará ni huella de su existencia. Cuando gastes la última carga, el talismán se disolverá en un limo apestoso y se destruirá."}],"requirements":{"attunement":true,"bearer":[{"kind":"other","keys":[],"explanation":"Objeto maravilloso, legendario (requiere sintonización por parte de una criatura de alineamiento malvado)"}],"presence":"worn","explanation":"Objeto maravilloso, legendario (requiere sintonización por parte de una criatura de alineamiento malvado)"},"weapon":null,"armor":null,"resources":[],"capabilities":[{"id":"official-assisted-rule","name":"Reglas del objeto","activation":"other","trigger":"","requirements":{"attunement":true,"bearer":[{"kind":"other","keys":[],"explanation":"Objeto maravilloso, legendario (requiere sintonización por parte de una criatura de alineamiento malvado)"}],"presence":"worn","explanation":"Objeto maravilloso, legendario (requiere sintonización por parte de una criatura de alineamiento malvado)"},"target":"Según la regla oficial.","range":"","duration":"Según la regla oficial.","concentration":"spell-dependent","costs":[],"consumeQuantity":0,"effects":[{"id":"assisted-rule","condition":"","kind":"unmodeled","explanation":"Este objeto simboliza el mal impenitente. Una criatura cuyo alineamiento no sea ni bueno ni malvado sufrirá 6d6 de daño necrótico si lo toca. En cambio, si es de alineamiento bueno, sufrirá 8d6 de daño necrótico. En ambos casos, la criatura sufrirá el daño de nuevo cada vez que sostenga o lleve puesto el talismán al terminar su turno.\n\nSi eres un clérigo o paladín malvado, puedes usar el talismán como símbolo sagrado y obtienes un bonificador de +2 a las tiradas de ataque de conjuro mientras lo lleves puesto o lo sostengas.\n\nEl talismán tiene 6 cargas. Si lo llevas puesto o lo sostienes, puedes usar una acción para gastar 1 de sus cargas y elegir una criatura que puedas ver en el suelo a 36 m o menos de ti. Si el objetivo tiene alineamiento bueno, una grieta ardiente se abrirá bajo él. Deberá superar una tirada de salvación de Destreza con CD 20 o se caerá por la grieta y será destruido sin dejar ningún resto mortal. A continuación, la grieta se cerrará y no quedará ni huella de su existencia. Cuando gastes la última carga, el talismán se disolverá en un limo apestoso y se destruirá.","original":{"page":263,"source":"srd-5.1-es-equipment","metadata":"Objeto maravilloso, legendario (requiere s